import numpy as np

class DPFedAvg:
    def __init__(self, clip_norm, noise_multiplier, num_clients):
        self.clip_norm = clip_norm
        self.noise_multiplier = noise_multiplier
        self.num_clients = num_clients
        self.privacy_budget = 0.0
    def clip_update(self, client_update, global_weights):
        delta = {k: client_update[k] - global_weights[k] for k in client_update}
        flat_delta = np.concatenate([v.flatten() for v in delta.values()])
        norm = np.linalg.norm(flat_delta)
        clip_coef = min(1.0, self.clip_norm / (norm + 1e-8))
        clipped_delta = {k: v * clip_coef for k, v in delta.items()}
        return {k: global_weights[k] + clipped_delta[k] for k in global_weights}
    def add_noise(self, aggregated_update):
        sigma = self.noise_multiplier * self.clip_norm
        return {k: v + np.random.normal(0, sigma, v.shape) for k, v in aggregated_update.items()}
    def dp_aggregate(self, client_updates, global_weights):
        clipped = [self.clip_update(u, global_weights) for u in client_updates]
        avg = {k: sum(c[k] for c in clipped) / len(clipped) for k in global_weights}
        return self.add_noise(avg)
